"use strict";

let SelectionSpecialRoot = null;
let SelectionSpecialPickContainer = null;
let SelectionSpecialReplaceContainer = null;
let SelectionSpecialNewAbilityCard = null;
let SelectionSpecialTimerValue = null;
let SelectionSpecialTitle = null;

let SelectionSpecialLocalPlayerID = -1;

let SelectionSpecialMode = "none"; // "pick" / "replace"
let SelectionSpecialEndTime = -1;

// 替换模式图标按钮
let SelectionSpecialReplaceIcons = [];

function SelectionSpecial_NormalizeChoices(rawChoices) {
    // 返回标准 JS Array，元素顺序按 1,2,3...
    if (!rawChoices) return [];

    // 如果已经是 Array，直接返回
    if (rawChoices instanceof Array) return rawChoices;

    // Panorama 常见：{ "1": {...}, "2": {...} } 没有 length
    let arr = [];
    let keys = Object.keys(rawChoices);

    // 只取数字 key，并按数字排序
    keys = keys
        .filter(k => String(parseInt(k)) === k || /^\d+$/.test(k))
        .map(k => parseInt(k))
        .sort((a, b) => a - b);

    for (let i = 0; i < keys.length; i++) {
        let k = String(keys[i]);
        arr.push(rawChoices[k]);
    }
    return arr;
}

function SelectionSpecial_EnsurePickSlots(count) {
    let container = SelectionSpecialPickContainer;
    if (!container) return;

    while (container.GetChildCount() > count) {
        container.GetChild(container.GetChildCount() - 1).DeleteAsync(0);
    }

    while (container.GetChildCount() < count) {
        let slot = $.CreatePanel("Panel", container, "");
        slot.AddClass("SelectionSpecialCardSlot");
    }
}


// ============================ 初始化 ============================

(function () {
    $.Schedule(0.0, SelectionSpecial_Init);
})();

function SelectionSpecial_Init() {
    SelectionSpecialRoot = $.GetContextPanel();
    SelectionSpecialPickContainer = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialPickContainer");
    SelectionSpecialReplaceContainer = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialReplaceContainer");
    SelectionSpecialNewAbilityCard = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialNewAbilityCard");
    SelectionSpecialTimerValue = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialTimerValue");
    SelectionSpecialTitle = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialTitle");

    SelectionSpecialLocalPlayerID = Players.GetLocalPlayer();

    // 订阅服务器事件
    GameEvents.Subscribe("selection_special_show", SelectionSpecial_OnShowPick);
    GameEvents.Subscribe("selection_special_replace_show", SelectionSpecial_OnShowReplace);
    GameEvents.Subscribe("selection_special_close", SelectionSpecial_OnClose);

    // 默认隐藏
    SelectionSpecial_Hide();
}

// ============================ 基础 UI 显示控制 ============================

function SelectionSpecial_Show() {
    if (!SelectionSpecialRoot) return;
    SelectionSpecialRoot.RemoveClass("Hidden");
    SelectionSpecialRoot.AddClass("Show");
}

function SelectionSpecial_Hide() {
    if (!SelectionSpecialRoot) return;

    SelectionSpecialRoot.AddClass("Hidden");
    SelectionSpecialRoot.RemoveClass("Show");

    // 清理模式 class
    SelectionSpecialRoot.RemoveClass("ModePick");
    SelectionSpecialRoot.RemoveClass("ModeReplace");

    // 模式面板
    let pickMode = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialPickMode");
    let replaceMode = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialReplaceMode");
    if (pickMode) pickMode.AddClass("Hidden");
    if (replaceMode) replaceMode.AddClass("Hidden");

    SelectionSpecialMode = "none";
    SelectionSpecialEndTime = -1;
}

// ============================ Pick 三选一 ============================

function SelectionSpecial_OnShowPick(event) {
    if (!event) return;
    if (event.player_id !== SelectionSpecialLocalPlayerID) return;

    SelectionSpecialMode = "pick";

    // Root class：让 CSS 可以区分 Pick/Replace
    SelectionSpecialRoot.RemoveClass("ModeReplace");
    SelectionSpecialRoot.AddClass("ModePick");

    // 标题
    if (SelectionSpecialTitle) {
        SelectionSpecialTitle.text = $.Localize("#selection_special_pick_title");
    }

    // 切换面板
    let pickMode = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialPickMode");
    let replaceMode = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialReplaceMode");
    if (pickMode) pickMode.RemoveClass("Hidden");
    if (replaceMode) replaceMode.AddClass("Hidden");

    // 显示 UI
    SelectionSpecial_Show();

    // 卡片数据
    let choices = SelectionSpecial_NormalizeChoices(event.choices);
    let count = choices.length;

    SelectionSpecial_EnsurePickSlots(count);

    for (let i = 0; i < count; i++) {
        let data = choices[i] || {};

        /* 【修改点 2】从 Slot 取容器 */
        let slot = SelectionSpecialPickContainer.GetChild(i);
        if (!slot) continue;

        /* 【修改点 3】每次清空 Slot，避免残留 */
        slot.RemoveAndDeleteChildren();

        /* 【修改点 4】在 Slot 内创建 Card */
        let panel = $.CreatePanel("Panel", slot, "");
        panel.BLoadLayoutSnippet("SelectionSpecialCard");

        let abilityName = data.ability || "";
        let image = data.image || "";

        SelectionSpecial_FillCard(panel, {
            ability: abilityName,
            image: image,
            ability_image: data.ability_image || "",
            growth: data.growth || null,
        });

        // 空卡片禁用
        if (!abilityName) {
            panel.AddClass("Disabled");
            panel.enabled = false;
            panel.hittest = false;
        } else {
            panel.RemoveClass("Disabled");
            panel.enabled = true;
            panel.hittest = true;

            // 点击事件（服务器端索引用 1-based）
            (function (index) {
                panel.SetPanelEvent("onactivate", function () {
                    SelectionSpecial_OnPickCardClicked(index);
                });
            })(i + 1);
        }
    }

    /* 【修改点 5】不再需要隐藏多余卡牌
       Slot 数量已经 == count，多余的已被删除 */

    /* 倒计时保持不变 */
    SelectionSpecial_StartCountdown(event.time_limit || 0);
}

function SelectionSpecial_OnPickCardClicked(choiceIndex) {
    GameEvents.SendCustomGameEventToServer("selection_special_choice", {
        PlayerID: SelectionSpecialLocalPlayerID,
        choice_index: choiceIndex,
    });
}

// ============================ Replace 替换 ============================

function SelectionSpecial_OnShowReplace(event) {
    $.Msg("[Replace] OnShowReplace called, event = ", event);
    if (!event) {
        $.Msg("[Replace] abort: event is null");
        return;
    }

    if (event.player_id !== SelectionSpecialLocalPlayerID) {
        $.Msg("[Replace] abort: wrong player_id", event.player_id, SelectionSpecialLocalPlayerID);
        return;
    }


    let pickMode = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialPickMode");
    let replaceMode = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialReplaceMode");

    $.Msg("[Replace] pickMode =", pickMode);
    $.Msg("[Replace] replaceMode =", replaceMode);
    $.Msg("[Replace] SelectionSpecialReplaceContainer =", SelectionSpecialReplaceContainer);
    $.Msg("[Replace] SelectionSpecialNewAbilityCard =", SelectionSpecialNewAbilityCard);

    if (!replaceMode || !SelectionSpecialReplaceContainer || !SelectionSpecialNewAbilityCard) {
        $.Msg("[Replace] abort: required panel missing");
        return;
    }

    SelectionSpecialMode = "replace";

    let title = SelectionSpecialRoot.FindChildTraverse("SelectionSpecialTitle");
    if (title) {
        title.text = "替换技能";
    }

    pickMode.AddClass("Hidden");
    replaceMode.RemoveClass("Hidden");

    SelectionSpecial_Show();

    $.Msg("[Replace] clearing NewAbilityCard children");
    SelectionSpecialNewAbilityCard.RemoveAndDeleteChildren();
    let newCard = $.CreatePanel("Panel", SelectionSpecialNewAbilityCard, "");
    $.Msg("[Replace] newCard created =", newCard);

    let ok = newCard.BLoadLayoutSnippet("SelectionSpecialCard");
    $.Msg("[Replace] BLoadLayoutSnippet result =", ok);

    $.Msg(
        "[Replace] newCard children count =",
        newCard.GetChildCount()
    );

    for (let i = 0; i < newCard.GetChildCount(); i++) {
        $.Msg("[Replace] newCard child", i, "=", newCard.GetChild(i));
    }

    SelectionSpecial_FillCard(newCard, {
        ability: event.new_ability || "",
        image: event.new_image || "",
        ability_image: event.new_ability_image || "",
        growth: event.new_growth || null,
    });

    newCard.AddClass("Disabled");
    newCard.enabled = false;
    newCard.hittest = false;

    const rawSlots = event && event.slots;
    let slots = [];
    for (let k in rawSlots) {
        slots.push(rawSlots[k]);
    }

    SelectionSpecial_BuildReplaceIcons(slots.length);

    for (let i = 0; i < slots.length; i++) {
        let data = slots[i];
        let host = SelectionSpecialReplaceIcons[i]; // 这是承载 snippet 的 Panel
        if (!host) continue;

        // snippet 内真正可点击的 Button 和 Image
        let btn = host.GetChild(0); // SelectionSpecialIconButton
        let icon = host.FindChildTraverse("ReplaceIcon");

        let abilityName = (data && data.ability) || "";
        let image = (data && data.image) || "";
        let index = (data && data.index) || -1;

        // 填图
        if (icon) {
            if (image) icon.SetImage(image);
            else icon.SetImage("");

            // 清理 tooltip（防残留）
            icon.ClearPanelEvent("onmouseover");
            icon.ClearPanelEvent("onmouseout");

            // 绑定 tooltip（只在 replace 需要）
            if (abilityName) {
                icon.SetPanelEvent("onmouseover", function () {
                    $.DispatchEvent("DOTAShowAbilityTooltip", icon, abilityName);
                });
                icon.SetPanelEvent("onmouseout", function () {
                    $.DispatchEvent("DOTAHideAbilityTooltip", icon);
                });
            }
        }

        // 点击替换（绑在按钮上）
        if (!btn) btn = host; // 保险
        btn.ClearPanelEvent("onactivate");

        if (!abilityName || index < 0) {
            btn.AddClass("Disabled");
            btn.enabled = false;
        } else {
            btn.RemoveClass("Disabled");
            btn.enabled = true;
            (function (idx) {
                btn.SetPanelEvent("onactivate", function () {
                    SelectionSpecial_OnReplaceCardClicked(idx);
                });
            })(index);
        }
    }

    // 多余隐藏
    for (let j = slots.length; j < SelectionSpecialReplaceIcons.length; j++) {
        SelectionSpecialReplaceIcons[j].AddClass("Hidden");
    }


    // 倒计时
    let timeLimit = event.time_limit || 0;
    SelectionSpecial_StartCountdown(timeLimit);

}

function SelectionSpecial_BuildReplaceIcons(count) {
    if (!SelectionSpecialReplaceContainer) return;

    for (let i = SelectionSpecialReplaceIcons.length; i < count; i++) {
        let p = $.CreatePanel("Panel", SelectionSpecialReplaceContainer, "");
        p.BLoadLayoutSnippet("SelectionSpecialIconButton");
        SelectionSpecialReplaceIcons.push(p);
    }

    for (let i = 0; i < count; i++) {
        SelectionSpecialReplaceIcons[i].RemoveClass("Hidden");
    }
}

function SelectionSpecial_OnReplaceCardClicked(slotIndex) {
    GameEvents.SendCustomGameEventToServer("selection_special_replace_choice", {
        PlayerID: SelectionSpecialLocalPlayerID,
        ability_index: slotIndex,
    });
}

// ============================ 公共：填充卡片 UI ============================

function SelectionSpecial_FillCard(panel, data) {
    if (!panel || !data) return;

    let abilityName = data.ability || "";
    let imagePath = data.image || "";

    let icon = panel.FindChildTraverse("AbilityIcon");
    let nameLabel = panel.FindChildTraverse("AbilityName");
    let descLabel = panel.FindChildTraverse("AbilityDesc");

    // 大图（卡面）
    if (icon) {
        icon.SetImage(imagePath || "");
    }

    // 名称/描述（本地化）
    if (nameLabel) {
        nameLabel.text = abilityName ? $.Localize("#" + abilityName) : "";
    }
    if (descLabel) {
        descLabel.text = abilityName ? $.Localize("#" + abilityName + "_Description") : "";
    }

    let abilityTitle = panel.FindChildTraverse("AbilityTitle");
    if (abilityTitle) {
        if (abilityName) {
            abilityTitle.text = $.Localize("#selection_special_ability_title");
            abilityTitle.RemoveClass("Hidden");
        } else {
            abilityTitle.text = "";
            abilityTitle.AddClass("Hidden");
        }
    }

    // 额外：技能图标 + tooltip
    let extraIcon = panel.FindChildTraverse("AbilityExtraIcon");
    if (extraIcon) {
        let smallIconPath = data.ability_image || "";
        if (smallIconPath) {
            extraIcon.SetImage(smallIconPath);
            extraIcon.RemoveClass("Hidden");
        } else {
            extraIcon.AddClass("Hidden");
        }

        extraIcon.SetPanelEvent("onmouseover", function () {
            if (abilityName) {
                $.DispatchEvent("DOTAShowAbilityTooltip", extraIcon, abilityName);
            }
        });
        extraIcon.SetPanelEvent("onmouseout", function () {
            $.DispatchEvent("DOTAHideAbilityTooltip", extraIcon);
        });
    }

    // 额外：成长属性
    let growthTitle = panel.FindChildTraverse("GrowthTitle");
    if (growthTitle) {
        if (data.growth && abilityName) {
            growthTitle.text = $.Localize("#selection_special_growth_title");
            growthTitle.RemoveClass("Hidden");
        } else {
            growthTitle.text = "";
            growthTitle.AddClass("Hidden");
        }
    }

    let growthContainer = panel.FindChildTraverse("GrowthContainer");
    if (growthContainer) {
        growthContainer.RemoveAndDeleteChildren();

        let growth = data.growth;
        if (growth && typeof growth === "object") {
            // KV 顺序不稳定：排序输出，保证 UI 稳定
            let keys = Object.keys(growth);
            keys.sort();

            for (let i = 0; i < keys.length; i++) {
                let k = keys[i];
                let v = growth[k];

                if (v === null || v === undefined) continue;
                if (typeof v === "string" && v.length === 0) continue;

                let line = $.CreatePanel("Label", growthContainer, "");
                line.AddClass("SelectionSpecialGrowthLine");
                line.text = SelectionSpecial_FormatGrowthLine(k, v);
            }
        }
    }
}

function SelectionSpecial_FormatGrowthLine(attrKey, rawVal) {
    let keyBase = SelectionSpecial_NormalizeAttrKey(attrKey);
    let locKey = "#dota_ability_variable_" + keyBase;
    let name = $.Localize(locKey);

    // 找不到本地化：兜底
    if (!name || name === locKey || name.indexOf("dota_ability_variable_") !== -1) {
        name = keyBase;
    }

    // 数值格式化
    let num = Number(rawVal);
    let isNumber = !isNaN(num);

    let formatted;
    if (!isNumber) {
        formatted = String(rawVal);
    } else {
        const isPctField = attrKey.indexOf("Pct") !== -1;

        const isTenThousandNoSymbol =
            attrKey.indexOf("ProjectileCooldown") !== -1 ||
            attrKey.indexOf("SkillCooldown") !== -1 ||
            attrKey.indexOf("AttackSpeed") !== -1;

        if (isPctField) {
            // Pct：显示百分号
            let pctVal = num / 100.0;
            formatted = SelectionSpecial_FormatSignedNumber(pctVal, 2) + "%";
        } else if (isTenThousandNoSymbol) {
            // 万分比 → 百分值，但不加 %
            let val = num / 100.0;
            let decimals = (Math.abs(val - Math.round(val)) < 0.00001) ? 0 : 2;
            formatted = SelectionSpecial_FormatSignedNumber(val, decimals);
        } else {
            // 普通数值
            let decimals = (Math.abs(num - Math.round(num)) < 0.00001) ? 0 : 2;
            formatted = SelectionSpecial_FormatSignedNumber(num, decimals);
        }
    }

    return name + " " + formatted;
}

function SelectionSpecial_NormalizeAttrKey(attrKey) {
    // AttackSpeed_Flat -> AttackSpeed
    // CritFlat_Flat -> CritFlat
    // FinalDamagePct_Flat -> FinalDamagePct
    if (!attrKey) return "";

    let parts = String(attrKey).split("_");
    if (parts.length >= 2) {
        parts.pop(); // 去掉最后一个后缀段
        return parts.join("_");
    }
    return String(attrKey);
}

function SelectionSpecial_FormatSignedNumber(num, decimals) {
    let n = Number(num);
    if (isNaN(n)) return String(num);

    let abs = Math.abs(n);
    let s = (decimals && decimals > 0) ? abs.toFixed(decimals) : String(Math.round(abs));

    // 去掉多余尾随 0
    if (decimals && decimals > 0) {
        s = s.replace(/\.00$/, "").replace(/(\.\d)0$/, "$1");
    }

    if (n > 0) return "+ " + s;
    if (n < 0) return "- " + s;
    return s;
}

// ============================ 倒计时 ============================

function SelectionSpecial_StartCountdown(timeLimit) {
    let now = Game.GetGameTime();
    SelectionSpecialEndTime = now + (timeLimit || 0);

    SelectionSpecial_UpdateCountdown(); // 先立即更新一次
}

function SelectionSpecial_UpdateCountdown() {
    if (!SelectionSpecialRoot || SelectionSpecialRoot.BHasClass("Hidden")) {
        return;
    }

    if (SelectionSpecialEndTime < 0) {
        if (SelectionSpecialTimerValue) SelectionSpecialTimerValue.text = "";
        return;
    }

    let now = Game.GetGameTime();
    let remain = Math.max(Math.ceil(SelectionSpecialEndTime - now), 0);

    if (SelectionSpecialTimerValue) {
        SelectionSpecialTimerValue.text = String(remain);
    }

    $.Schedule(0.1, SelectionSpecial_UpdateCountdown);
}

// ============================ 放弃按钮 / 关闭 ============================

function SelectionSpecial_OnGiveUp() {
    GameEvents.SendCustomGameEventToServer("selection_special_giveup", {
        PlayerID: SelectionSpecialLocalPlayerID,
    });
}

function SelectionSpecial_OnClose(event) {
    if (!event) return;
    if (event.player_id !== SelectionSpecialLocalPlayerID) return;

    SelectionSpecial_Hide();
}

